  if (blkR) { o += gnStop(ARp[0] - 18, ARp[1]); o += T(ARp[0] - 4, ARp[1] + 30, "receptor blocked", "gn-sm gn-badt", "middle"); }
  /* the androgen-effect readout at the nucleus */
