    if (b.hasAttribute("data-amk")) { var v = b.getAttribute("data-amv"); st[b.getAttribute("data-amk")] = isNaN(+v) ? v : +v; if (D.ONSET) D[D.ONSET](st, b.getAttribute("data-amk"), D); stop(); update(); }
