    function f1(n) { return Math.round(n * 10) / 10; }
    function T(x, y, s, cls, a) { return '<text class="t' + (cls ? " " + cls : "") + '" x="' + f1(x) + '" y="' + f1(y) + '"' + (a ? ' text-anchor="' + a + '"' : "") + ">" + s + "</text>"; }
    function L(x, y, s, px, py, a, cls) { return '<g class="am-callout"><path class="lead" d="M' + f1(a === "end" ? x + 3 : x - 3) + " " + f1(y - 4) + "L" + f1(px) + " " + f1(py) + '"/><circle class="dot" cx="' + f1(px) + '" cy="' + f1(py) + '" r="1.8"/>' + T(x, y, s, cls, a) + "</g>"; }
